/* AIVIC_FUNCTION_BUNDLE_START owner=validateReportSubmissionTime exports=validateReportSubmissionTime */
const __aivicBundle_44_validateReportSubmissionTime = (() => {
  function validateReportSubmissionTime(params: {
    userId: string;
    currentTimeJst: Date;
    timezoneId: string;
  }): {
    isSubmissionTarget: boolean;
    targetDate: string;
    utcTime: string;
    jstTime: string;
    monthBoundaryHandled: boolean;
  } {
    if (params["userId"] === undefined || params["userId"] === null) { throw new Error("userId is required"); }
    const { currentTimeJst, timezoneId } = params;
  
    // JST時刻から ISO 8601 形式の文字列を取得
    const jstTimeString = currentTimeJst.toLocaleString('ja-JP', {
      timeZone: timezoneId,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false,
    });
  
    // JST時刻文字列をパース (YYYY-MM-DD HH:mm:ss 形式)
    const [datePart, timePart] = jstTimeString.split(' ');
    const [year, month, day] = datePart.split('/');
    const targetDate = `${year}-${month}-${day}`;
  
    // JST時刻を ISO 8601 形式で表現 (+09:00 オフセット付き)
    const jstTime = `${year}-${month}-${day}T${timePart}+09:00`;
  
    // UTC時刻を計算
    // currentTimeJst は既に Date オブジェクトなので、UTC に変換
    const utcDate = new Date(currentTimeJst);
    const utcTimeString = utcDate.toISOString();
  
    // 月をまたぐ判定
    // JST の日付と UTC の日付が異なる場合、月境界を越えている
    const jstDateObj = new Date(currentTimeJst.toLocaleString('en-US', { timeZone: timezoneId }));
    const utcDateObj = new Date(utcTimeString);
    const monthBoundaryHandled =
      jstDateObj.getUTCDate() !== utcDateObj.getUTCDate() ||
      jstDateObj.getUTCMonth() !== utcDateObj.getUTCMonth();
  
    return {
      isSubmissionTarget: true,
      targetDate,
      utcTime: utcTimeString,
      jstTime,
      monthBoundaryHandled,
    };
  }
  return { validateReportSubmissionTime };
})();
export const validateReportSubmissionTime = __aivicBundle_44_validateReportSubmissionTime.validateReportSubmissionTime;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateReportSubmissionTime */

/* AIVIC_FUNCTION_BUNDLE_START owner=sendConfirmationEmailsOnReporting exports=sendConfirmationEmailsOnReporting */
const __aivicBundle_45_sendConfirmationEmailsOnReporting = (() => {
  function sendConfirmationEmailsOnReporting(
    submission_user_id: string,
    submission_timestamp: Date,
    submission_user_email: string,
    department_head_email: string,
    submission_content: ReportContent,
    deadline_start_time: Date,
    deadline_end_time: Date,
    email_send_hook: (to_email: string, subject: string, body: string) => void
  ): {
    is_within_deadline: boolean;
    is_nanosecond_truncated: boolean;
    sent_at_timestamp: Date;
    email_delivery_status: string;
    emails_sent: number;
  } {
    const submissionTimeMs = submission_timestamp.getTime();
    
    const nanoseconds = submission_timestamp.getMilliseconds() * 1000000 + (submission_timestamp.getTime() % 1) * 1000000;
    const isNanosecondTruncated = nanoseconds % 1000 !== 0;
    
    const truncatedSubmissionMs = Math.floor(submissionTimeMs / 1000) * 1000 + Math.floor((submission_timestamp.getMilliseconds() * 1000) / 1000);
    
    const deadlineStartMs = deadline_start_time.getTime();
    const deadlineEndMs = deadline_end_time.getTime();
    
    const isWithinDeadline = truncatedSubmissionMs >= deadlineStartMs && truncatedSubmissionMs <= deadlineEndMs;
    
    let emailsCount = 0;
    let deliveryStatus = 'skipped';
    
    if (isWithinDeadline) {
      const emailSubject = '朝会報告確認';
      const emailBody = `
  朝会報告が受け付けられました。
  
  【前日の成果】
  ${submission_content.yesterday_achievement}
  
  【本日の予定】
  ${submission_content.today_plan}
  
  【現在の課題】
  ${submission_content.current_issues}
  
  報告者ID: ${submission_user_id}
  `;
      
      email_send_hook(submission_user_email, emailSubject, emailBody);
      emailsCount++;
      
      email_send_hook(department_head_email, emailSubject, emailBody);
      emailsCount++;
      
      deliveryStatus = 'success';
    }
    
    return {
      is_within_deadline: isWithinDeadline,
      is_nanosecond_truncated: isNanosecondTruncated,
      sent_at_timestamp: submission_timestamp,
      email_delivery_status: deliveryStatus,
      emails_sent: emailsCount
    };
  }
  return { sendConfirmationEmailsOnReporting };
})();
