const __aivicBundle_52_sendConfirmationEmailsToManagerAndSender = (() => {
  async function sendConfirmationEmailsToManagerAndSender(params: {
    submitted_members: Array<any>;
    manager_user: {
      user_id: string;
      user_name: string;
      email_address: string;
      department_id: string;
      role: string;
    };
    morning_meeting_time: Date;
    email_service: {
      send: (to: string, subject: string, body: string) => Promise<{ success: boolean; message_id: string }>;
    };
  }): Promise<{ emails_sent: number; status: string; reason?: string }> {
    const { submitted_members, manager_user, morning_meeting_time, email_service } = params;
  
    if (!submitted_members || submitted_members.length === 0) {
      return {
        emails_sent: 0,
        status: 'early_return',
        reason: 'no_submitted_members',
      };
    }
  
    let emails_sent = 0;
  
    const managerSubject = '朝会報告確認 - 部員提出状況';
    const managerBody = buildManagerEmailBody(submitted_members, morning_meeting_time);
  
    try {
      await email_service.send(manager_user.email_address, managerSubject, managerBody);
      emails_sent += 1;
    } catch (error) {
      return {
        emails_sent,
        status: 'partial_failure',
        reason: `Failed to send email to manager: ${error instanceof Error ? error.message : 'Unknown error'}`,
      };
    }
  
    for (const member of submitted_members) {
      const memberEmail = member.email_address || member.email;
      const memberName = member.user_name || member.name || 'Member';
  
      if (!memberEmail) {
        continue;
      }
  
      const senderSubject = '朝会報告確認 - 提出完了';
      const senderBody = buildSenderEmailBody(memberName, morning_meeting_time);
  
      try {
        await email_service.send(memberEmail, senderSubject, senderBody);
        emails_sent += 1;
      } catch (error) {
        continue;
      }
    }
  
    return {
      emails_sent,
      status: 'success',
    };
  }
  
  function buildManagerEmailBody(submitted_members: Array<any>, morning_meeting_time: Date): string {
    const meetingTimeStr = morning_meeting_time.toISOString();
    const memberList = submitted_members
      .map((m) => `- ${m.user_name || m.name || 'Unknown'}`)
      .join('\n');
  
    return `朝会報告確認\n\n以下の部員から報告が提出されました。\n\n${memberList}\n\n朝会時刻: ${meetingTimeStr}`;
  }
  
  function buildSenderEmailBody(memberName: string, morning_meeting_time: Date): string {
    const meetingTimeStr = morning_meeting_time.toISOString();
    return `${memberName}様\n\nご報告ありがとうございました。\n\n朝会時刻: ${meetingTimeStr}`;
  }
  return { sendConfirmationEmailsToManagerAndSender };
})();
