/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateDailyReports exports=aggregateDailyReports */
const __aivicBundle_54_aggregateDailyReports = (() => {
  function aggregateDailyReports(params: {
    database: {
      users: Array<any>;
      daily_reports: Array<any>;
      submission_history: Array<any>;
      email_logs: Array<any>;
    };
    report_date: string;
    morning_meeting_time: Date;
  }): {
    total_submitted: number;
    total_not_submitted: number;
    total_delayed: number;
    reports: Array<{
      report_id: string;
      user_id: string;
      user_name: string;
      yesterday_achievements: string;
      today_plans: string;
      current_issues: string;
      submission_time: string;
    }>;
  } {
    const { database, report_date, morning_meeting_time } = params;
    const { users, daily_reports, submission_history } = database;
  
    const reportsByDate = daily_reports.filter(
      (report: any) => report.report_date === report_date
    );
  
    const submittedUserIds = new Set(
      reportsByDate.map((report: any) => report.user_id)
    );
  
    const deadlineTime = new Date(morning_meeting_time);
    deadlineTime.setMinutes(deadlineTime.getMinutes() - 30);
  
    const reports: Array<{
      report_id: string;
      user_id: string;
      user_name: string;
      yesterday_achievements: string;
      today_plans: string;
      current_issues: string;
      submission_time: string;
    }> = [];
  
    let total_submitted = 0;
    let total_delayed = 0;
  
    for (const report of reportsByDate) {
      const user = users.find((u: any) => u.user_id === report.user_id);
      const submissionHistory = submission_history.find(
        (sh: any) =>
          sh.user_id === report.user_id &&
          sh.submission_date === report_date
      );
  
      const submissionTime = submissionHistory
        ? new Date(
            `${submissionHistory.submission_date}T${submissionHistory.submission_time}`
          )
        : new Date(report.submission_datetime);
  
      const isDelayed = submissionTime > deadlineTime;
  
      if (isDelayed) {
        total_delayed++;
      } else {
        total_submitted++;
      }
  
      reports.push({
        report_id: report.report_id,
        user_id: report.user_id,
        user_name: user?.user_name || report.user_name || "",
        yesterday_achievements: report.yesterday_achievement || "",
        today_plans: report.today_plan || "",
        current_issues: report.current_issues || "",
        submission_time: submissionTime.toISOString(),
      });
    }
  
    const total_not_submitted = users.length - submittedUserIds.size;
  
    return {
      total_submitted,
      total_not_submitted,
      total_delayed,
      reports,
    };
  }
  return { aggregateDailyReports };
})();
export const aggregateDailyReports = __aivicBundle_54_aggregateDailyReports.aggregateDailyReports;
/* AIVIC_FUNCTION_BUNDLE_END owner=aggregateDailyReports */

