/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateDailyReportsWithTimestampSort exports=aggregateDailyReportsWithTimestampSort */
const __aivicBundle_57_aggregateDailyReportsWithTimestampSort = (() => {
  function aggregateDailyReportsWithTimestampSort(
    reports: Array<{
      user_id?: string;
      employee_id?: string;
      user_name?: string;
      employee_name?: string;
      yesterday_achievement?: string;
      today_plan?: string;
      issues?: string;
      issue?: string;
      submitted_at: Date;
    }>,
  ): Array<{
    user_id?: string;
    employee_id?: string;
    user_name?: string;
    employee_name?: string;
    yesterday_achievement?: string;
    today_plan?: string;
    issues?: string;
    issue?: string;
    submitted_at: Date;
  }> {
    if (!reports || reports.length === 0) {
      return [];
    }
  
    const deduplicatedMap = new Map<string, typeof reports[0]>();
  
    for (const report of reports) {
      const userId = report.user_id ?? report.employee_id ?? '';
      if (userId) {
        deduplicatedMap.set(userId, report);
      }
    }
  
    const deduplicated = Array.from(deduplicatedMap.values());
  
    const sorted = deduplicated.sort((a, b) => {
      const timeA = a.submitted_at.getTime();
      const timeB = b.submitted_at.getTime();
      return timeA - timeB;
    });
  
    return sorted;
  }
  return { aggregateDailyReportsWithTimestampSort };
})();
