const __aivicBundle_92_determineReportDeadlineStatus = (() => {
  function determineReportDeadlineStatus(input: {
    currentDateTime: Date;
    morningMeetingStartTime: string;
    reportDeadlineDay: string;
  }): {
    status: "within-deadline" | "delayed" | "overdue";
    isAcceptable: boolean;
    statusMessage: string;
  } {
    const { currentDateTime, morningMeetingStartTime, reportDeadlineDay } = input;
  
    // Parse morning meeting time (HH:mm format)
    const [meetingHour, meetingMinute] = morningMeetingStartTime
      .split(":")
      .map(Number);
  
    // Create deadline datetime: reportDeadlineDay at morningMeetingStartTime
    const deadlineDate = new Date(reportDeadlineDay);
    deadlineDate.setUTCHours(meetingHour, meetingMinute, 0, 0);
  
    // Compare current time with deadline
    const timeDiffMs = deadlineDate.getTime() - currentDateTime.getTime();
    const timeDiffMinutes = Math.floor(timeDiffMs / (1000 * 60));
  
    let status: "within-deadline" | "delayed" | "overdue";
    let isAcceptable: boolean;
    let statusMessage: string;
  
    if (timeDiffMinutes >= 0) {
      status = "within-deadline";
      isAcceptable = true;
      statusMessage = `Report submitted within deadline. ${timeDiffMinutes} minutes before deadline.`;
    } else if (timeDiffMinutes < 0 && timeDiffMinutes >= -15) {
      status = "delayed";
      isAcceptable = true;
      statusMessage = `Report submitted ${Math.abs(timeDiffMinutes)} minutes after deadline, but within acceptable grace period.`;
    } else {
      status = "overdue";
      isAcceptable = false;
      statusMessage = `Report submitted ${Math.abs(timeDiffMinutes)} minutes after deadline. Overdue.`;
    }
  
    return {
      status,
      isAcceptable,
      statusMessage,
    };
  }
  return { determineReportDeadlineStatus };
})();
