/* AIVIC_FUNCTION_BUNDLE_START owner=judgePromptLoopTermination exports=judgePromptLoopTermination */
const __aivicBundle_98_judgePromptLoopTermination = (() => {
  function judgePromptLoopTermination(input: any): any {
    const {
      member_id,
      member_name,
      termination_condition,
      report_submitted_at,
      meeting_start_at,
    } = input;
  
    const shouldTerminate = true;
    const terminationReason = termination_condition;
    const recommendedAction = determineRecommendedAction(termination_condition);
    const elapsedMinutes = calculateElapsedMinutes(report_submitted_at);
    const minutesUntilMeeting = calculateMinutesUntilMeeting(
      report_submitted_at,
      meeting_start_at
    );
  
    return {
      should_terminate: shouldTerminate,
      member_id: member_id,
      member_name: member_name,
      termination_reason: terminationReason,
      recommended_action: recommendedAction,
      elapsed_minutes: elapsedMinutes,
      minutes_until_meeting: minutesUntilMeeting,
    };
  }
  
  function determineRecommendedAction(terminationCondition: string): string {
    switch (terminationCondition) {
      case "report_submitted":
        return "stop";
      case "max_attempts_reached":
        return "notifyManager";
      case "timeout_exceeded":
        return "notifyManager";
      case "meeting_imminent":
        return "stop";
      default:
        return "continue";
    }
  }
  
  function calculateElapsedMinutes(reportSubmittedAt: Date): number {
    const now = new Date();
    const diffMs = now.getTime() - reportSubmittedAt.getTime();
    return Math.floor(diffMs / (1000 * 60));
  }
  
  function calculateMinutesUntilMeeting(
    reportSubmittedAt: Date,
    meetingStartAt: Date
  ): number {
    const diffMs = meetingStartAt.getTime() - reportSubmittedAt.getTime();
    return Math.floor(diffMs / (1000 * 60));
  }
  return { judgePromptLoopTermination };
})();
export const judgePromptLoopTermination = __aivicBundle_98_judgePromptLoopTermination.judgePromptLoopTermination;
