/* AIVIC_FUNCTION_BUNDLE_START owner=checkPromptLoopTerminationCondition exports=checkPromptLoopTerminationCondition */
const __aivicBundle_103_checkPromptLoopTerminationCondition = (() => {
  function checkPromptLoopTerminationCondition(context: {
    max_prompt_attempts?: number | null;
    current_prompt_count?: number;
    last_response_received_at?: Date | null;
    timeout_minutes?: number;
    promptStartTime?: Date;
    promptTimeoutMinutes?: number;
    currentPromptAttemptCount?: number;
    reportReceivedTime?: Date | null;
    morningMeetingStartTime?: Date;
    currentTime?: Date;
    maxPromptAttempts?: number | null;
  }): PromptTerminationResult {
    // Validate required field: max_prompt_attempts (or maxPromptAttempts)
    const maxAttempts = context.max_prompt_attempts ?? context.maxPromptAttempts;
    if (maxAttempts === null || maxAttempts === undefined) {
      throw new Error("規定催促回数上限が指定されていません");
    }
  
    // Extract parameters with fallback to alternative names
    const currentAttemptCount = context.current_prompt_count ?? context.currentPromptAttemptCount ?? 0;
    const timeoutMinutes = context.timeout_minutes ?? context.promptTimeoutMinutes ?? 0;
    const reportReceivedTime = context.last_response_received_at ?? context.reportReceivedTime;
    
    // Calculate elapsed time
    const now = context.currentTime ?? new Date();
    const promptStart = context.promptStartTime ?? new Date();
    const elapsedMinutes = Math.floor((now.getTime() - promptStart.getTime()) / (1000 * 60));
    
    // Calculate minutes until morning meeting
    const meetingTime = context.morningMeetingStartTime ?? new Date();
    const minutesUntilMeeting = Math.floor((meetingTime.getTime() - now.getTime()) / (1000 * 60));
    
    // Determine termination conditions
    const isTimeoutExceeded = elapsedMinutes >= timeoutMinutes;
    const isMaxAttemptsReached = currentAttemptCount >= maxAttempts;
    const isReportReceived = reportReceivedTime !== null && reportReceivedTime !== undefined;
    const isMeetingImminent = minutesUntilMeeting <= 30;
    
    // Determine if should terminate
    const shouldTerminate = isTimeoutExceeded || isMaxAttemptsReached || isReportReceived || isMeetingImminent;
    
    // Determine recommended action
    let recommendedAction: 'continue' | 'stop' | 'notifyManager' = 'continue';
    let reason: 'max_attempts_reached' | 'timeout_exceeded' | 'report_received' | 'meeting_imminent' | 'unknown' = 'unknown';
    
    if (isReportReceived) {
      recommendedAction = 'stop';
      reason = 'report_received';
    } else if (isMeetingImminent) {
      recommendedAction = 'notifyManager';
      reason = 'meeting_imminent';
    } else if (isMaxAttemptsReached) {
      recommendedAction = 'notifyManager';
      reason = 'max_attempts_reached';
    } else if (isTimeoutExceeded) {
      recommendedAction = 'notifyManager';
      reason = 'timeout_exceeded';
    }
    
    return {
      shouldTerminate,
      reason,
      elapsedMinutes,
      minutesUntilMeeting,
      recommendedAction,
    };
  }
  return { checkPromptLoopTerminationCondition };
})();
export const checkPromptLoopTerminationCondition = __aivicBundle_103_checkPromptLoopTerminationCondition.checkPromptLoopTerminationCondition;
