/* AIVIC_FUNCTION_BUNDLE_START owner=notifyUnsubmittedMembers exports=notifyUnsubmittedMembers */
const __aivicBundle_110_notifyUnsubmittedMembers = (() => {
  function notifyUnsubmittedMembers(
    input: any,
    unsubmittedMembers?: any,
    sendEmailFn?: any
  ): { notificationSent: boolean; notifiedCount: number; failureCount: number; timestamp: string } {
    const timestamp = new Date().toISOString();
  
    // 引数パターン1: 配列のみ (シグネチャ互換)
    if (Array.isArray(input) && unsubmittedMembers === undefined) {
      const members = input;
      if (!Array.isArray(members) || members.length === 0) {
        throw new Error("未提出部員情報リストが空です");
      }
      return {
        notificationSent: false,
        notifiedCount: members.length,
        failureCount: 0,
        timestamp,
      };
    }
  
    // 引数パターン2: object + array + function (テスト観測パターン)
    if (
      input &&
      typeof input === "object" &&
      !Array.isArray(input) &&
      Array.isArray(unsubmittedMembers)
    ) {
      const config = input as {
        department_head_user_id?: string;
        department_head_email?: string | null;
        morning_meeting_start_time?: Date;
      };
      const members = unsubmittedMembers as Array<{
        user_id: string;
        user_name: string;
        department_id: string;
      }>;
      const emailFn = sendEmailFn as ((email: string) => boolean) | undefined;
  
      // Validation: 部長のメールアドレスが null
      if (config.department_head_email === null) {
        throw new Error("部長のメールアドレスが設定されていません");
      }
  
      // Validation: 未提出部員リストが空
      if (!Array.isArray(members) || members.length === 0) {
        throw new Error("未提出部員情報リストが空です");
      }
  
      let notifiedCount = 0;
      let failureCount = 0;
  
      // 各部員に通知を送信
      for (const member of members) {
        if (emailFn && typeof emailFn === "function") {
          const success = emailFn(member.user_id);
          if (success) {
            notifiedCount++;
          } else {
            failureCount++;
          }
        } else {
          // emailFn が提供されない場合は成功と見なす
          notifiedCount++;
        }
      }
  
      return {
        notificationSent: failureCount === 0 && notifiedCount > 0,
        notifiedCount,
        failureCount,
        timestamp,
      };
    }
  
    // デフォルト: 空配列エラー
    throw new Error("未提出部員情報リストが空です");
  }
  return { notifyUnsubmittedMembers };
})();
