const __aivicBundle_115_stopPromptingJudgment = (() => {
  function stopPromptingJudgment(input: any): { shouldStop: boolean; reason: string } {
    // Validate required field: targetMemberId must not be null
    if (input.targetMemberId === null || input.targetMemberId === undefined) {
      throw new Error("部員IDは必須です");
    }
  
    const { promotionCount = 0, maxPromotionAttempts = 3, elapsedMinutes = 0, timeoutMinutes = 15, hasReportBeenReceived = false, minutesUntilMeeting = 30 } = input;
  
    // Check if report has been received
    if (hasReportBeenReceived === true) {
      return {
        shouldStop: true,
        reason: "報告が届きました",
      };
    }
  
    // Check if max attempts reached
    if (promotionCount >= maxPromotionAttempts) {
      return {
        shouldStop: true,
        reason: "最大試行回数に達しました",
      };
    }
  
    // Check if timeout exceeded
    if (elapsedMinutes >= timeoutMinutes) {
      return {
        shouldStop: true,
        reason: "許容時間を超過しました",
      };
    }
  
    // Check if meeting starts within 30 minutes
    if (minutesUntilMeeting <= 30) {
      return {
        shouldStop: true,
        reason: "朝会開始が30分以内です",
      };
    }
  
    // Continue prompting
    return {
      shouldStop: false,
      reason: "催促を継続します",
    };
  }
  return { stopPromptingJudgment };
})();
