/* AIVIC_FUNCTION_BUNDLE_START owner=fetchReportArrivalStatus exports=fetchReportArrivalStatus */
const __aivicBundle_127_fetchReportArrivalStatus = (() => {
  function fetchReportArrivalStatus(params: {
    reportDate: string;
    teamMemberIds: string[];
    submittedReports: Array<{ memberId: string; submittedAt: Date }>;
    scheduledMeetingTime: Date;
  }): {
    allSubmitted: boolean;
    submittedCount: number;
    notSubmittedMembers: Array<{ memberId: string; memberName: string }>;
    delayedMembers: Array<{
      memberId: string;
      memberName: string;
      delayMinutes: number;
    }>;
  } {
    if (params["reportDate"] === undefined || params["reportDate"] === null) { throw new Error("reportDate is required"); }
    const { teamMemberIds, submittedReports, scheduledMeetingTime } = params;
  
    const submittedMemberMap = new Map(
      submittedReports.map((report) => [report.memberId, report.submittedAt])
    );
  
    const notSubmittedMembers: Array<{
      memberId: string;
      memberName: string;
    }> = [];
    const delayedMembers: Array<{
      memberId: string;
      memberName: string;
      delayMinutes: number;
    }> = [];
  
    for (const memberId of teamMemberIds) {
      if (!submittedMemberMap.has(memberId)) {
        notSubmittedMembers.push({
          memberId,
          memberName: "",
        });
      } else {
        const submittedAt = submittedMemberMap.get(memberId)!;
        const delayMilliseconds =
          submittedAt.getTime() - scheduledMeetingTime.getTime();
        const delayMinutes = Math.ceil(delayMilliseconds / (1000 * 60));
  
        if (delayMinutes > 0) {
          delayedMembers.push({
            memberId,
            memberName: "",
            delayMinutes,
          });
        }
      }
    }
  
    const submittedCount = submittedReports.length;
    const allSubmitted =
      notSubmittedMembers.length === 0 && delayedMembers.length === 0;
  
    return {
      allSubmitted,
      submittedCount,
      notSubmittedMembers,
      delayedMembers,
    };
  }
  return { fetchReportArrivalStatus };
})();
export const fetchReportArrivalStatus = __aivicBundle_127_fetchReportArrivalStatus.fetchReportArrivalStatus;
/* AIVIC_FUNCTION_BUNDLE_END owner=fetchReportArrivalStatus */

/* AIVIC_FUNCTION_BUNDLE_START owner=getReportArrivalStatus exports=getReportArrivalStatus */
const __aivicBundle_128_getReportArrivalStatus = (() => {
  function getReportArrivalStatus(
    arg1: string | any[] | { periodStart?: Date; periodEnd?: Date; submissions?: any[] },
    arg2?: Date,
    arg3?: string
  ): any {
    // Handle case 1: departmentId validation (string input)
    if (typeof arg1 === 'string') {
      if (arg1 === '') {
        return {
          code: 'INVALID_DEPARTMENT_ID',
          message: '部門IDは必須項目です'
        };
      }
    }
  
    // Handle case 2: Array of reports with meetingStartTime and morningMeetingDate
    if (Array.isArray(arg1) && arg2 instanceof Date && typeof arg3 === 'string') {
      const reports = arg1;
      const meetingStartTime = arg2;
      const morningMeetingDate = arg3;
  
      const reportArrivals = reports.map((report) => {
        const submittedAt = report.submittedAt;
        const isOnTime = submittedAt <= meetingStartTime;
        const status = isOnTime ? 'on_time' : 'late';
        const delayMinutes = isOnTime
          ? 0
          : Math.floor((submittedAt.getTime() - meetingStartTime.getTime()) / (1000 * 60));
  
        return {
          reportId: report.reportId,
          userId: report.userId,
          status,
          submittedAt,
          delayMinutes: Math.abs(delayMinutes)
        };
      });
  
      const totalArrived = reportArrivals.length;
      const displayLabel = `${morningMeetingDate}朝会分：到着${totalArrived}件`;
  
      return {
        morningMeetingDate,
        totalArrived,
        reportArrivals,
        displayLabel
      };
    }
  
    // Handle case 3: Period-based aggregation (object with periodStart, periodEnd, submissions)
    if (
      typeof arg1 === 'object' &&
      !Array.isArray(arg1) &&
      arg1.periodStart instanceof Date &&
      arg1.periodEnd instanceof Date &&
      Array.isArray(arg1.submissions)
    ) {
      const { periodStart, periodEnd, submissions } = arg1;
      const arrivalsByDate: { [key: string]: number } = {};
      let totalArrivalCount = 0;
      let excludedSubmissionCount = 0;
  
      submissions.forEach((submission) => {
        const submissionDate = submission.submissionDate;
  
        // Check if submission is within the target period
        if (submissionDate >= periodStart && submissionDate <= periodEnd) {
          const dateKey = submissionDate.toISOString().split('T')[0];
          arrivalsByDate[dateKey] = (arrivalsByDate[dateKey] || 0) + 1;
          totalArrivalCount++;
        } else {
          excludedSubmissionCount++;
        }
      });
  
      return {
        targetPeriodStart: periodStart,
        targetPeriodEnd: periodEnd,
        arrivalsByDate,
        totalArrivalCount,
        excludedSubmissionCount
      };
    }
  
    // Default fallback
    return {
      arrivedReports: [],
      missingReports: [],
      lateReports: [],
      arrivalRate: 0,
      allArrived: false
    };
  }
  return { getReportArrivalStatus };
})();
