/* AIVIC_FUNCTION_BUNDLE_START owner=validateReportArrivalStatus exports=validateReportArrivalStatus */
const __aivicBundle_129_validateReportArrivalStatus = (() => {
  function validateReportArrivalStatus(input: any): any {
    // 入力が null または undefined の場合はエラー
    if (!input) {
      throw new Error("入力パラメータが必要です");
    }
  
    // confirm_mail_received_at が null または undefined の場合はエラーをスロー
    if (input.confirm_mail_received_at === null || input.confirm_mail_received_at === undefined) {
      throw new Error("確認メール受信日時が必要です");
    }
  
    // プラン仕様の入力形式に対応
    if (input.reportDate !== undefined && input.submittedReports !== undefined && input.expectedEmployeeIds !== undefined && input.reportDeadlineTime !== undefined) {
      const { submittedReports, expectedEmployeeIds, reportDeadlineTime } = input;
  
      const arrivedReports: Array<{ employeeId: string; submittedAt: Date }> = [];
      const lateReports: Array<{ employeeId: string; submittedAt: Date; delayMinutes: number }> = [];
      const submittedEmployeeIds = new Set<string>();
  
      for (const report of submittedReports) {
        submittedEmployeeIds.add(report.employeeId);
        const delayMs = report.submittedAt.getTime() - reportDeadlineTime.getTime();
  
        if (delayMs <= 0) {
          arrivedReports.push({
            employeeId: report.employeeId,
            submittedAt: report.submittedAt,
          });
        } else {
          const delayMinutes = Math.ceil(delayMs / (1000 * 60));
          lateReports.push({
            employeeId: report.employeeId,
            submittedAt: report.submittedAt,
            delayMinutes,
          });
        }
      }
  
      const missingReports: Array<{ employeeId: string }> = [];
      for (const employeeId of expectedEmployeeIds) {
        if (!submittedEmployeeIds.has(employeeId)) {
          missingReports.push({ employeeId });
        }
      }
  
      const totalExpected = expectedEmployeeIds.length;
      const totalArrived = arrivedReports.length + lateReports.length;
      const arrivalRate = totalExpected > 0 ? Math.round((totalArrived / totalExpected) * 100) : 0;
      const allArrived = missingReports.length === 0 && lateReports.length === 0;
  
      return {
        arrivedReports,
        missingReports,
        lateReports,
        arrivalRate,
        allArrived,
      };
    }
  
    // テスト互換性: snake_case 入力形式に対応
    if (input.user_id !== undefined && input.report_sent_at !== undefined && input.report_sent_status !== undefined) {
      // confirm_mail_received_at の検証は既に上で実施済み
      return {
        user_id: input.user_id,
        user_name: input.user_name,
        department_id: input.department_id,
        department_name: input.department_name,
        report_sent_at: input.report_sent_at,
        report_sent_status: input.report_sent_status,
        confirm_mail_received_at: input.confirm_mail_received_at,
      };
    }
  
    throw new Error("無効な入力形式です");
  }
  return { validateReportArrivalStatus };
})();
export const validateReportArrivalStatus = __aivicBundle_129_validateReportArrivalStatus.validateReportArrivalStatus;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateReportArrivalStatus */

