/* AIVIC_FUNCTION_BUNDLE_START owner=checkReportArrivalStatus exports=checkReportArrivalStatus */
const __aivicBundle_134_checkReportArrivalStatus = (() => {
  function checkReportArrivalStatus(input: any): any {
    // Handle both the test case (with report_id and database) and the planned signature
    if (input.report_id && input.database) {
      // Test case: validate report completeness
      const report = input.database.reports.get(input.report_id);
      
      if (!report) {
        throw new Error(`Report not found: ${input.report_id}`);
      }
      
      // Check for required fields
      const requiredFields = ['yesterday_achievement', 'today_plan', 'current_issues'];
      const missingFields = requiredFields.filter(field => report[field] === null || report[field] === undefined || report[field] === '');
      
      if (missingFields.length > 0) {
        throw new Error(`REPORT_DATA_INCOMPLETE: 必須項目が欠落しています - ${missingFields.join(', ')}`);
      }
      
      return {
        isValid: true,
        report_id: report.report_id,
        submission_status: report.submission_status,
      };
    }
    
    // Planned signature case: check arrival status
    const { submittedReports, allUserIds, deadlineTime } = input;
    
    const submittedUserIds = submittedReports.map((r: any) => r.userId);
    const notSubmittedUserIds = allUserIds.filter((id: string) => !submittedUserIds.includes(id));
    
    const delayedUserIds = submittedReports
      .filter((r: any) => r.submittedAt > deadlineTime)
      .map((r: any) => ({
        userId: r.userId,
        delayMs: r.submittedAt.getTime() - deadlineTime.getTime(),
      }));
    
    const submissionRate = allUserIds.length > 0 
      ? Math.round((submittedUserIds.length / allUserIds.length) * 100)
      : 0;
    
    return {
      isAllSubmitted: notSubmittedUserIds.length === 0,
      submittedUserIds,
      notSubmittedUserIds,
      delayedUserIds,
      submissionRate,
    };
  }
  return { checkReportArrivalStatus };
})();
export const checkReportArrivalStatus = __aivicBundle_134_checkReportArrivalStatus.checkReportArrivalStatus;
/* AIVIC_FUNCTION_BUNDLE_END owner=checkReportArrivalStatus */

