/* AIVIC_FUNCTION_BUNDLE_START owner=validateReportFormat exports=validateReportFormat */
const __aivicBundle_143_validateReportFormat = (() => {
  function validateReportFormat(input: any): any {
    // Normalize input to handle multiple field naming conventions
    const yesterday = input?.yesterdayWork ?? input?.yesterday_accomplishment ?? input?.yesterday ?? '';
    const today = input?.todayPlan ?? input?.today_plan ?? input?.today ?? '';
    const issues = input?.issues ?? input?.current_challenge ?? input?.current_issues ?? input?.issue ?? '';
  
    const errors: Array<{ field: string; reason: string }> = [];
  
    // Validation: each field must be 1-500 characters
    const validateField = (value: string, fieldName: string, displayName: string): boolean => {
      if (typeof value !== 'string' || value.length === 0 || value.length > 500) {
        errors.push({
          field: fieldName,
          reason: `${displayName}が入力されていません` || '1文字以上500文字以下である必要があります',
        });
        return false;
      }
      return true;
    };
  
    const isYesterdayValid = validateField(yesterday, 'yesterdayWork', '昨日やったこと');
    const isTodayValid = validateField(today, 'todayPlan', '今日やること(today)');
    const isIssuesValid = validateField(issues, 'issues', '抱えている課題');
  
    const isValid = isYesterdayValid && isTodayValid && isIssuesValid;
  
    // Determine output format based on input structure
    // If input has userId, return extended format with userId and hasX flags
    if (input?.userId) {
      return {
        isValid,
        userId: input.userId,
        hasYesterday: isYesterdayValid,
        hasToday: isTodayValid,
        hasIssue: isIssuesValid,
        errors,
      };
    }
  
    // If input has snake_case fields, return snake_case format
    if (input?.yesterday_accomplishment !== undefined || input?.today_plan !== undefined || input?.current_challenge !== undefined) {
      return {
        validation_passed: isValid,
        error_messages: errors.map((e) => e.reason),
      };
    }
  
    // If input has status-related expectations, return status format
    if (input?.today === null || input?.issue !== undefined) {
      return {
        status: isValid ? 'valid' : 'warning',
        message: errors.length > 0 ? errors.map((e) => e.reason).join('; ') : '',
        isValid,
        canSubmit: isValid,
        severity: isValid ? undefined : 'warning',
      };
    }
  
    // Default format
    return {
      isValid,
      errors,
    };
  }
  return { validateReportFormat };
})();
export const validateReportFormat = __aivicBundle_143_validateReportFormat.validateReportFormat;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateReportFormat */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateReportContent exports=validateReportContent */
const __aivicBundle_144_validateReportContent = (() => {
  function validateReportContent(input: {
    yesterday_accomplishment?: string;
    today_plan?: string;
    current_issues?: string;
    yesterdayWork?: string;
    todayPlan?: string;
    issues?: string;
  }): {
    status: string;
    message: string;
    isComplete?: boolean;
    missingFields?: string[];
  } {
    const yesterday =
      input.yesterday_accomplishment ?? input.yesterdayWork ?? "";
    const today = input.today_plan ?? input.todayPlan ?? "";
    const issues = input.current_issues ?? input.issues ?? "";
  
    const isEmpty = (value: string): boolean => !value || value.trim() === "";
  
    const yesterdayEmpty = isEmpty(yesterday);
    const todayEmpty = isEmpty(today);
    const issuesEmpty = isEmpty(issues);
  
    const allEmpty = yesterdayEmpty && todayEmpty && issuesEmpty;
  
    if (allEmpty) {
      return {
        status: "warning",
        message:
          "昨日やったこと、今日やること、抱えている課題のいずれか1つ以上の入力が必須です",
        isComplete: false,
        missingFields: ["昨日やったこと", "今日やること", "抱えている課題"],
      };
    }
  
    const missingFields: string[] = [];
    if (yesterdayEmpty) missingFields.push("昨日やったこと");
    if (todayEmpty) missingFields.push("今日やること");
    if (issuesEmpty) missingFields.push("抱えている課題");
  
    if (missingFields.length > 0) {
      return {
        status: "warning",
        message: `以下の項目が未入力です: ${missingFields.join("、")}`,
        isComplete: false,
        missingFields,
      };
    }
  
    return {
      status: "success",
      message: "すべての項目が入力されています",
      isComplete: true,
      missingFields: [],
    };
  }
  return { validateReportContent };
})();
export const validateReportContent = __aivicBundle_144_validateReportContent.validateReportContent;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateReportContent */

