/* AIVIC_FUNCTION_BUNDLE_START owner=sendUnsumittedReportReminderNotification exports=sendUnsumittedReportReminderNotification */
const __aivicBundle_150_sendUnsumittedReportReminderNotification = (() => {
  interface SendUnsumittedReportReminderNotificationInput {
    [key: string]: any;
  }
  
  interface SendUnsumittedReportReminderNotificationMailResult {
    recipient_email: string;
    status: string;
    mail_body: string;
    mail_send_id?: string;
    sent_at?: string;
  }
  
  interface SendUnsumittedReportReminderNotificationResult {
    total_unsumitted_count: number;
    reminder_mails_sent: number;
    unsumitted_user_ids: string[];
    mail_send_results: MailSendResult[];
  }
  
   async function sendUnsumittedReportReminderNotification(
    input: SendUnsumittedReportReminderNotificationInput
  ): Promise<SendUnsumittedReportReminderNotificationResult> {
    const {
      submission_history,
      employees,
      morning_meeting_time,
      department_id,
    } = input;
  
    // Extract submitted user IDs from submission history
    const submittedUserIds = new Set(
      submission_history.map((record) => record.user_id)
    );
  
    // Filter employees in the department who have not submitted
    const unsubmittedEmployees = employees.filter(
      (emp) =>
        emp.department_id === department_id &&
        !submittedUserIds.has(emp.user_id)
    );
  
    const unsubmittedUserIds = unsubmittedEmployees.map((emp) => emp.user_id);
    const mailSendResults: MailSendResult[] = [];
  
    // Send reminder emails to each unsubmitted employee
    for (const employee of unsubmittedEmployees) {
      const mailBody = `朝会報告がまだ送信されていません。\n\n部員名: ${employee.user_name}\nメール: ${employee.email_address}\n\n朝会開始時刻: ${morning_meeting_time.toISOString()}\n\nお早めにご報告ください。`;
  
      try {
        const response = await fetch("/api/send-mail", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            recipient_email: employee.email_address,
            subject: "朝会報告の催促",
            body: mailBody,
          }),
        });
  
        const responseData = await response.json();
  
        mailSendResults.push({
          success: true,
          recipient_emails: [employee.email_address],
          sent_count: 1,
          failed_count: 0,
          sent_at: new Date(responseData.sent_at || new Date().toISOString()),
          status: responseData.status || "sent",
          mail_body: mailBody,
          mail_send_id: responseData.mail_send_id,
        });
      } catch {
        mailSendResults.push({
          success: false,
          recipient_emails: [employee.email_address],
          sent_count: 0,
          failed_count: 1,
          status: "failed",
          mail_body: mailBody,
        });
      }
    }
  
    const successCount = mailSendResults.filter((r) => r.success).length;
  
    return {
      total_unsumitted_count: unsubmittedEmployees.length,
      reminder_mails_sent: successCount,
      unsumitted_user_ids: unsubmittedUserIds,
      mail_send_results: mailSendResults,
    };
  }
  return { sendUnsumittedReportReminderNotification };
})();
