const __aivicBundle_156_sendReminderEmail = (() => {
  function sendReminderEmail(payload: ReminderEmailPayload): EmailSendResult {
    if (payload["departmentName"] === undefined || payload["departmentName"] === null) { throw new Error("departmentName is required"); }
    // Validate recipient email format
    if (!payload.recipientEmail || !isValidEmailFormatInternal(payload.recipientEmail)) {
      return {
        success: false,
        errorMessage: 'メールアドレスが不正です'
      };
    }
  
    // Validate required payload fields
    if (!payload.recipientName || !payload.unreportedMemberNames || payload.unreportedMemberNames.length === 0) {
      return {
        success: false,
        errorMessage: '必須項目が不足しています'
      };
    }
  
    // Validate deadline and meeting time
    if (!payload.reportDeadlineTime || !payload.morningMeetingTime) {
      return {
        success: false,
        errorMessage: '期限情報が不足しています'
      };
    }
  
    // Validate and use departmentName
    if (!payload.departmentName || String(payload.departmentName).trim() === '') {
      return {
        success: false,
        errorMessage: '部門情報が不足しています'
      };
    }
  
    // Generate message ID and timestamp
    const sentAt = new Date();
    const messageId = generateMessageIdForReminderInternal(payload.recipientEmail, sentAt);
  
    return {
      success: true,
      messageId: messageId,
      sentAt: sentAt
    };
  }
  
  function isValidEmailFormatInternal(email: string): boolean {
    if (typeof email !== 'string') {
      return false;
    }
    const trimmed = email.trim();
    const atIndex = trimmed.indexOf('@');
    if (atIndex <= 0 || atIndex === trimmed.length - 1) {
      return false;
    }
    const localPart = trimmed.substring(0, atIndex);
    const domainPart = trimmed.substring(atIndex + 1);
    if (localPart.length === 0 || domainPart.length === 0) {
      return false;
    }
    if (!domainPart.includes('.')) {
      return false;
    }
    return true;
  }
  
  function generateMessageIdForReminderInternal(email: string, sentAt: Date): string {
    const timestamp = sentAt.getTime();
    const emailHash = email.split('').reduce((acc, char) => {
      return ((acc << 5) - acc) + char.charCodeAt(0);
    }, 0);
    const hashStr = Math.abs(emailHash).toString(16).substring(0, 8);
    const timeStr = timestamp.toString(16).substring(0, 8);
    return `msg_${timeStr}${hashStr}`;
  }
  return { sendReminderEmail };
})();
export const sendReminderEmail = __aivicBundle_156_sendReminderEmail.sendReminderEmail;
/* AIVIC_FUNCTION_BUNDLE_END owner=sendReminderEmail */

